def numDistinct(s, t):
    m, n = len(s), len(t)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    # Empty target has one way: select nothing
    for i in range(m + 1):
        dp[i][0] = 1
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s[i-1] == t[j-1]:
                # Either include this char or don't
                dp[i][j] = dp[i-1][j-1] + dp[i-1][j]
            else:
                # Can't use this char, carry forward
                dp[i][j] = dp[i-1][j]
    return dp[m][n]

print(numDistinct('rabbbit', 'rabbit'))  # 3 (rab_b_it, rab_bi_t, rabb_i_t)
print(numDistinct('babgbag', 'bag'))  # 5

# Space-optimized version
def numDistinct_optimized(s, t):
    m, n = len(s), len(t)
    dp = [0] * (n + 1)
    dp[0] = 1
    for i in range(1, m + 1):
        for j in range(n, 0, -1):  # Backwards to avoid overwriting
            if s[i-1] == t[j-1]:
                dp[j] += dp[j-1]
    return dp[n]

print(numDistinct_optimized('rabbbit', 'rabbit'))  # 3
