def findNumberOfLIS(nums):
    if not nums:
        return 0
    n = len(nums)
    # lengths[i] = length of LIS ending at index i
    lengths = [1] * n
    # counts[i] = number of LIS of length lengths[i] ending at index i
    counts = [1] * n
    for i in range(1, n):
        for j in range(i):
            if nums[j] < nums[i]:
                if lengths[j] + 1 > lengths[i]:
                    lengths[i] = lengths[j] + 1
                    counts[i] = counts[j]
                elif lengths[j] + 1 == lengths[i]:
                    counts[i] += counts[j]
    max_length = max(lengths)
    return sum(count for i, count in enumerate(counts) if lengths[i] == max_length)

print(findNumberOfLIS([1, 3, 4, 4, 5]))  # 2 ([1,3,4,5], [1,3,4,5] via second 4)
# Actually: [1,3,4,5] and [1,3,4,5] are same sequences. With second 4: two distinct
print(findNumberOfLIS([2, 2, 2, 2, 2]))  # 5 (five sequences of length 1)
print(findNumberOfLIS([1, 2, 4, 3, 5]))  # 2 ([1,2,4,5], [1,2,3,5])

# Time: O(n^2), Space: O(n)
