def stoneGameV(stoneValue):
    # DP with memoization
    memo = {}
    def dp(start, end):
        if start == end:
            return 0  # Only one stone, can't play
        if start > end:
            return 0
        if (start, end) in memo:
            return memo[(start, end)]
        result = float('-inf')
        # Try all split points
        left_sum = 0
        right_sum = sum(stoneValue[start:end + 1])
        for i in range(start, end):
            left_sum += stoneValue[i]
            right_sum -= stoneValue[i]
            if left_sum > right_sum:
                result = max(result, left_sum + dp(start, i))
            elif left_sum < right_sum:
                result = max(result, right_sum + dp(i + 1, end))
            else:
                result = max(result, left_sum + dp(start, i), right_sum + dp(i + 1, end))
        memo[(start, end)] = result
        return result
    return dp(0, len(stoneValue) - 1)

print(stoneGameV([6, 2, 3, 4, 5, 5]))  # 22

