def stoneGameII(piles):
    memo = {}
    def dp(i, m):
        if i >= len(piles):
            return 0
        if (i, m) in memo:
            return memo[(i, m)]
        result = 0
        current_sum = 0
        for x in range(1, min(2 * m, len(piles) - i) + 1):
            current_sum += piles[i + x - 1]
            result = max(result, current_sum + dp(i + x, max(m, x)) - dp(i + x, max(m, x)))
        memo[(i, m)] = result
        return result
    total = sum(piles)
    alice = dp(0, 1)
    return alice
