def isInterleave(s1, s2, s3):
    if len(s1) + len(s2) != len(s3):
        return False
    m, n = len(s1), len(s2)
    # dp[i][j] = True if s3[0..i+j-1] can be formed from s1[0..i-1] and s2[0..j-1]
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True
    # Initialize first row (only s2)
    for j in range(1, n + 1):
        dp[0][j] = dp[0][j-1] and s2[j-1] == s3[j-1]
    # Initialize first column (only s1)
    for i in range(1, m + 1):
        dp[i][0] = dp[i-1][0] and s1[i-1] == s3[i-1]
    # Fill rest
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            # Use character from s1
            if dp[i-1][j] and s1[i-1] == s3[i+j-1]:
                dp[i][j] = True
            # Use character from s2
            if dp[i][j-1] and s2[j-1] == s3[i+j-1]:
                dp[i][j] = True
    return dp[m][n]

print(isInterleave('aabcc', 'dbbca', 'aadbbcbcac'))  # True
print(isInterleave('aab', 'dbbca', 'aadbbbaccc'))  # False
print(isInterleave('', '', ''))  # True

# Time: O(m*n), Space: O(m*n)
# Space-optimized: O(n) by using 1D DP
def isInterleave_optimized(s1, s2, s3):
    if len(s1) + len(s2) != len(s3):
        return False
    dp = [False] * (len(s2) + 1)
    for i in range(len(s1) + 1):
        for j in range(len(s2) + 1):
            k = i + j
            if i == 0 and j == 0:
                dp[j] = True
            elif i == 0:
                dp[j] = dp[j-1] and s2[j-1] == s3[k-1]
            elif j == 0:
                dp[j] = dp[j] and s1[i-1] == s3[k-1]
            else:
                dp[j] = (dp[j] and s1[i-1] == s3[k-1]) or (dp[j-1] and s2[j-1] == s3[k-1])
    return dp[len(s2)]
