def canCross(stones):
    if stones[1] != 1:
        return False
    stone_set = set(stones)
    # memo[stone] = set of possible last jump sizes to reach this stone
    memo = {stone: set() for stone in stones}
    memo[0].add(0)
    for stone in stones:
        for k in memo[stone]:
            # Next jumps: k-1, k, k+1
            for next_jump in [k - 1, k, k + 1]:
                if next_jump > 0 and stone + next_jump in stone_set:
                    memo[stone + next_jump].add(next_jump)
    return len(memo[stones[-1]]) > 0

print(canCross([0, 1, 3, 6, 9, 12, 15]))  # True
print(canCross([0, 1, 2, 3, 4, 8, 9, 11]))  # False

# Time: O(n^2), Space: O(n^2)
# Alternative BFS:
def canCross_bfs(stones):
    from collections import defaultdict, deque
    if stones[1] != 1:
        return False
    graph = defaultdict(set)
    for stone in stones:
        graph[stone].add(stone)
    for i, stone in enumerate(stones):
        for j in range(i + 1, len(stones)):
            diff = stones[j] - stone
            if diff > stone + 1:
                break  # Jump size increases
            if diff >= stone - 1:
                graph[stones[j]].add(diff)
    # BFS
    queue = deque([(0, 0)])
    visited = {(0, 0)}
    while queue:
        stone, k = queue.popleft()
        if stone == stones[-1]:
            return True
        for next_jump in [k - 1, k, k + 1]:
            if next_jump > 0 and stone + next_jump in graph:
                if (stone + next_jump, next_jump) not in visited:
                    visited.add((stone + next_jump, next_jump))
                    queue.append((stone + next_jump, next_jump))
    return False
