def minDistance(word1, word2):
    # LCS approach: deletions + insertions = len(word1) + len(word2) - 2*LCS
    m, n = len(word1), len(word2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if word1[i-1] == word2[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])
    lcs_length = dp[m][n]
    return m + n - 2 * lcs_length

print(minDistance('leetcode', 'etco'))  # 4
# LCS = 'eto' (length 3)
# Delete 5 from 'leetcode', Insert 0 to 'etco' = 5
# Actually: 8 + 4 - 2*3 = 6

print(minDistance('a', 'b'))  # 2

# Alternative: Edit distance (del/ins only, no replace)
def minInsertDelete(word1, word2):
    m, n = len(word1), len(word2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if word1[i-1] == word2[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = 1 + min(dp[i-1][j], dp[i][j-1])  # delete or insert
    return dp[m][n]

print(minInsertDelete('leetcode', 'etco'))  # 5
