def countSquares(matrix):
    m, n = len(matrix), len(matrix[0])
    dp = [[0] * n for _ in range(m)]
    count = 0
    for i in range(m):
        for j in range(n):
            if matrix[i][j] == 1:
                if i == 0 or j == 0:
                    dp[i][j] = 1
                else:
                    dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1
                count += dp[i][j]
    return count

print(countSquares([[0, 1], [1, 0]]))  # 1
print(countSquares([[1, 0, 1], [1, 1, 0], [1, 1, 0]]))  # 7
# dp[i][j] = side length of largest square with all 1s ending at (i,j)

# For general rectangles:
def countRectangles(matrix):
    m, n = len(matrix), len(matrix[0])
    # heights[j] = consecutive 1s above including current
    heights = [0] * n
    count = 0
    for i in range(m):
        for j in range(n):
            heights[j] = heights[j] + 1 if matrix[i][j] == 1 else 0
        # Count rectangles in this histogram
        for j in range(n):
            if heights[j] > 0:
                # Count rectangles with right edge at j
                min_height = heights[j]
                for k in range(j, -1, -1):
                    if heights[k] == 0:
                        break
                    min_height = min(min_height, heights[k])
                    # Rectangle from k to j with height min_height
                    count += min_height
    return count
