def longestPalindromeSubseq(s):
    # LPS(s) = LCS(s, reverse(s))
    reverse_s = s[::-1]
    m, n = len(s), len(reverse_s)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s[i-1] == reverse_s[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])
    return dp[m][n]

print(longestPalindromeSubseq('bbbab'))  # 4 ('bbbb')
print(longestPalindromeSubseq('cbbd'))  # 2 ('bb')

# Reconstruct the actual subsequence
def longestPalindromeSubseq_withPath(s):
    reverse_s = s[::-1]
    m, n = len(s), len(reverse_s)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s[i-1] == reverse_s[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])
    # Reconstruct
    lps = []
    i, j = m, n
    while i > 0 and j > 0:
        if s[i-1] == reverse_s[j-1]:
            lps.append(s[i-1])
            i -= 1
            j -= 1
        elif dp[i-1][j] > dp[i][j-1]:
            i -= 1
        else:
            j -= 1
    return ''.join(lps[::-1])

print(longestPalindromeSubseq_withPath('bbbab'))  # 'bbbb'
