def countArrangement(n):
    memo = {}
    def backtrack(index, used):
        if index == n + 1:
            return 1
        if used in memo:
            return memo[used]
        count = 0
        # Try placing each unused number at current position
        for num in range(1, n + 1):
            if not (used & (1 << (num - 1))):  # Not used
                # Check divisibility
                if index % num == 0 or num % index == 0:
                    used |= (1 << (num - 1))
                    count += backtrack(index + 1, used)
                    used &= ~(1 << (num - 1))
        memo[used] = count
        return count
    return backtrack(1, 0)

print(countArrangement(2))  # 2 ([2,1], [1,2])
print(countArrangement(3))  # 3 ([1,2,3], [3,2,1])
print(countArrangement(4))  # 8

# Alternative without memoization (slower):
def countArrangement_alt(n):
    def backtrack(index, used):
        if index == n + 1:
            return 1
        count = 0
        for num in range(1, n + 1):
            if num not in used:
                if index % num == 0 or num % index == 0:
                    used.add(num)
                    count += backtrack(index + 1, used)
                    used.remove(num)
        return count
    return backtrack(1, set())

print(countArrangement_alt(2))  # 2
