def generateParenthesis(n):
    result = []
    def backtrack(open_count, close_count, current):
        if open_count == n and close_count == n:
            result.append(current)
            return
        if open_count < n:
            backtrack(open_count + 1, close_count, current + '(')
        if close_count < open_count:
            backtrack(open_count, close_count + 1, current + ')')
    backtrack(0, 0, '')
    return result

print(generateParenthesis(3))
# ['((()))', '(()())', '(())()', '()(())', '()()()']

print(len(generateParenthesis(4)))  # 14 (Catalan number C_4)

# DP approach (Catalan numbers):
def generateParenthesis_dp(n):
    # dp[i] = list of all valid parentheses with i pairs
    dp = [[] for _ in range(n + 1)]
    dp[0] = ['']
    for i in range(1, n + 1):
        for j in range(i):  # j pairs inside, i-1-j pairs outside
            for left in dp[j]:
                for right in dp[i - 1 - j]:
                    dp[i].append('(' + left + ')' + right)
    return dp[n]

print(generateParenthesis_dp(2))  # ['(())', '()()']
